/* ── 「결」·겹낫표 지킴이 — 화면에 들어갈 글자에 있으면 던진다(바꾸지 않고 멈춤) ── */
function guard(where, s) { const t = String(s), i = t.indexOf('결'); if (i >= 0) throw new Error(where + ' 「결」 글자: ' + t.slice(Math.max(0, i - 30), i + 10)); if (/[『』]/.test(t)) throw new Error(where + ' 겹낫표: ' + t.slice(0, 60)); return t; }

/* ── extras 문자열 → 객체 ── */
const TYPE = { video: ['video', '🎥', ['concept', 'motivate']], q: ['fun_question', '💡', ['concept', 'basic_problem']], tip: ['tip', '🧩', ['concept', 'misconception']], real: ['real_world', '🌍', ['real_world', 'summary']], game: ['game', '🎮', ['leveled_problem', 'offline_activity']], x: ['misconception', '⚠️', ['misconception', 'basic_problem']], e: ['example', '📝', ['concept', 'offline_activity']], c: ['checklist', '✅', ['next_lesson']] };
const PFX = { video: 'v', q: 'q', tip: 't', real: 'r', game: 'g', x: 'x', e: 'e', c: 'c' };
function extras(n, list) {
  const cnt = {};
  return list.map(line => {
    const p = line.split('|'); const k = p[0]; cnt[k] = (cnt[k] || 0) + 1; const [type, icon, fit] = TYPE[k];
    const id = PFX[k] + '_l' + n + '_' + cnt[k];
    if (k === 'video') return { id, type, icon, title: p[1], url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(p[2]).replace(/%20/g, '+'), description: p[3], source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: fit };
    return { id, type, icon, title: p[1], content: p[2], fit_slides: fit };
  });
}
const lines = (t) => String(t).replace(/([다요])\. /g, '$1.\n').trim();
const clone = (o) => JSON.parse(JSON.stringify(o));

function problemData(p, title, body, fig) {
  const d = { title, scenario: { icon: '🧮', body }, question: p.q };
  if (fig) d.fig = fig;
  if (p.opts) { d.options = p.opts.map((t, i) => (i === p.ci ? { text: t, correct: true } : { text: t })); d.note = '풀이: ' + p.hints.join(' · ') + ' → **' + p.opts[p.ci] + '**'; }
  else { d.input = 'count_input'; d.answer = +p.a; d.note = '풀이: ' + p.hints.join(' · ') + ' → **' + p.a + '**'; }
  return d;
}

const LESSONS = {};
const keys = Object.keys(T);
keys.forEach((key, idx) => {
  const t = T[key], s = SRC[key], F = FIG[key], n = idx + 1;
  if (!s || !F) throw new Error(key + ' 재료 없음');
  if (s.slides.length !== 4 || s.problems.length !== 3) throw new Error(key + ' 재료 장 수');
  const ex = extras(n, t.ex); if (ex.length !== 22) throw new Error(key + ' extras ' + ex.length);
  const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevItems = idx === 0 ? PREV_EXIT : T[keys[idx - 1]].exit;
  const slides = [];
  const add = (block, stage, data, sug, tn) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: idx === 0 ? '1학기 마지막 시간엔 무엇을 했나요?' : '지난 시간엔 무엇을 했나요?', content: t.review, items: prevItems.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? PREV_KEY : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, kids: t.mot.kids, question: t.mot.q, img: 'assets/photo/math/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach(([si, tn], i) => { const src = s.slides[si]; const f = F.slides[si]; if (!f) throw new Error(key + ' 개념 장 ' + si + ' 그림 없음'); add('concept', '전개', { fig: clone(f), title: src.title, content: lines(src.text) }, csug[i], tn); });
  add('misconception', '전개', { title: '이런 생각을 조심해요', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach(([pi, body], i) => { const f = F.problems[pi]; if (!f) throw new Error(key + ' 문제 ' + pi + ' 그림 없음'); add('basic_problem', '기본문제', problemData(s.problems[pi], '기본 문제 ' + '①②③'[i], body, clone(f)), bsug[i]); });
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 곱셈을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  add('summary', '정리', { title: '오늘 배운 것', points: s.summary.split('\n').filter(Boolean).concat(t.sum.story), arrows: t.sum.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0][0], '🔧 과정·기능 — ' + t.self[0][1], '💛 가치·태도 — ' + t.self[0][2]], prompts: [t.self[1]] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '다음 단원엔' : '다음 시간엔', preview: t.nextText || (s.next + '. ' + s.next_q), emoji: t.next }, [id('c', 1)]);
  LESSONS[key] = {
    meta: { grade: 3, subject: '수학', term: 2, unit: 1, unit_title: '곱셈', n, title: t.title, std: STD_OF(n), duration_min: 40, lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '곰이·펭이 식품 안전 체험관', live_url: LIVE + s.file, source: '2022 개정 수학 3-2 지도서 1단원(' + s.guide + ') · ' + s.tb + ' — 자기주도 원문 없이 지도서에서 세움', src_key: key },
    slides, extras: ex
  };
  guard(key, JSON.stringify(LESSONS[key]));
});

